import openpyxl, sys
wb2 = openpyxl.load_workbook('/root/output/result.xlsx')
ts2 = wb2['Task']

print('Check formulas:')
for check_cell in ['H12','L17','H19','L24','H26','L31','H35','L40','H42','L47','H50','L50']:
    print(f'{check_cell}: {ts2[check_cell].value}')
print('Sheets:', wb2.sheetnames)

# Additional verifier-style checks
formula_ranges = []
for rows in [(12,17), (19,24), (26,31), (35,40), (42,47), (50,50)]:
    for r in range(rows[0], rows[1]+1):
        for c in ['H','I','J','K','L']:
            formula_ranges.append(f'{c}{r}')

bad = [(cell, ts2[cell].value) for cell in formula_ranges if not (isinstance(ts2[cell].value, str) and ts2[cell].value.startswith('='))]
if bad:
    print('BAD FORMULA CELLS:', bad)
    sys.exit(1)

# Check row-label to formula mapping for stats
expected_stats = {
    42: 'MIN', 43: 'MAX', 44: 'MEDIAN', 45: 'AVERAGE', 46: 'PERCENTILE', 47: 'PERCENTILE'
}
for r, fn in expected_stats.items():
    v = ts2[f'H{r}'].value
    if fn not in v:
        print('STAT ORDER MISMATCH', r, ts2[f'E{r}'].value, v)
        sys.exit(1)

# Check no extra sheets
if wb2.sheetnames != ['Task', 'Data']:
    print('SHEET MISMATCH')
    sys.exit(1)

print('Validation passed.')
